// Some portions generated by Codex
package org.eclipse.rdf4j.benchmark.common;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;

import org.apache.jena.query.Dataset;
import org.apache.jena.query.QueryExecution;
import org.apache.jena.query.QuerySolution;
import org.apache.jena.query.ReadWrite;
import org.eclipse.rdf4j.benchmark.rio.util.ThemeDataSetGenerator.Theme;
import org.junit.jupiter.api.Test;

/** Independent scalar and branch witnesses for the data-transformation catalog. */
class DataTransformationOracleFixtureCoverageTest {
	private static final String NS = DataTransformationOracleFixtureProfile.NAMESPACE;
	private static final long[] EXPECTED = { 4, 2, 6, 3, 5, 4, 4, 4, 3, 13, 5, 7, 10 };

	@Test
	void actualCatalogAggregatesHaveExactPositiveValues() {
		Dataset dataset = ThemeOracleBundleTool.jenaDataset(DataTransformationOracleFixtureProfile.generate());
		try {
			for (int index = 0; index < EXPECTED.length; index++) {
				List<QuerySolution> rows = select(dataset, query(index));
				assertEquals(1, rows.size(), "aggregate row q" + index);
				assertEquals(EXPECTED[index], rows.get(0).getLiteral("count").getLong(), "actual count q" + index);
				assertTrue(EXPECTED[index] > 0, "positive nonvacuous count q" + index);
			}
		} finally {
			dataset.close();
		}
	}

	@Test
	void sentinelsBoundariesAndDistinctFanoutHaveObservableWitnesses() {
		Dataset dataset = ThemeOracleBundleTool.jenaDataset(DataTransformationOracleFixtureProfile.generate());
		try {
			String q3 = query(3).replace("SELECT (COUNT(DISTINCT ?record) AS ?count) WHERE {",
					"SELECT ?record ?score WHERE {");
			Set<String> q3Records = subjects(select(dataset, q3));
			assertEquals(Set.of(NS + "record/0", NS + "record/1", NS + "record/4"), q3Records,
					"inclusive score bounds and -1 fallback");

			String q8 = query(8).replace("SELECT (COUNT(DISTINCT ?display) AS ?count) WHERE {",
					"SELECT ?record ?display WHERE {");
			List<QuerySolution> q8Rows = select(dataset, q8);
			assertTrue(q8Rows.stream()
					.anyMatch(row -> row.getResource("record").getURI().equals(NS + "never")
							&& row.getLiteral("display").getString().equals("short")),
					"sentinel bypasses length filter");
			assertTrue(q8Rows.stream()
					.anyMatch(row -> row.getResource("record").getURI().equals(NS + "record/missing")
							&& row.getLiteral("display").getString().equals("standard literal")),
					"unbound COALESCE fallback");
			assertFalse(q8Rows.stream().anyMatch(row -> row.getResource("record").getURI().equals(NS + "record/4")),
					"short bound value is excluded without sentinel");

			String q5 = query(5).replace("SELECT (COUNT(DISTINCT ?record) AS ?count) WHERE {",
					"SELECT ?record ?term WHERE {");
			assertEquals(2, select(dataset, q5).stream()
					.filter(row -> row.getResource("record").getURI().equals(NS + "record/0"))
					.count(), "both VALUES terms match before COUNT DISTINCT");

			String q12 = query(12).replace("SELECT (COUNT(DISTINCT ?transformed) AS ?count) WHERE {",
					"SELECT ?record ?transformed WHERE {");
			List<QuerySolution> raw = select(dataset, q12);
			assertEquals(18, raw.size(), "two 8-way optional products plus two individual mappings");
			Set<String> r0 = transformedFor(raw, NS + "record/0");
			Set<String> r1 = transformedFor(raw, NS + "record/1");
			assertEquals(8, r0.size());
			assertEquals(r0, r1, "different source records may compute the same transformed terms");
			assertEquals(10, raw.stream().map(row -> row.getLiteral("transformed").getString()).distinct().count(),
					"COUNT DISTINCT applies to transformed terms, not source records");
		} finally {
			dataset.close();
		}
	}

	private static String query(int index) {
		return ThemeQueryCatalog.queryFor(Theme.DATA_TRANSFORMATION, index);
	}

	private static Set<String> subjects(List<QuerySolution> rows) {
		return rows.stream().map(row -> row.getResource("record").getURI()).collect(Collectors.toSet());
	}

	private static Set<String> transformedFor(List<QuerySolution> rows, String subject) {
		return rows.stream()
				.filter(row -> row.getResource("record").getURI().equals(subject))
				.map(row -> row.getLiteral("transformed").getString())
				.collect(Collectors.toSet());
	}

	private static List<QuerySolution> select(Dataset dataset, String query) {
		List<QuerySolution> rows = new ArrayList<>();
		dataset.begin(ReadWrite.READ);
		try (QueryExecution execution = QueryExecution.dataset(dataset).query(query).build()) {
			var result = execution.execSelect();
			while (result.hasNext()) {
				rows.add(result.nextSolution());
			}
		} finally {
			dataset.end();
		}
		return rows;
	}
}
